        private readonly Dictionary<string, ChartDef> _chartDefs = new();

        private void InitChartDefs()
        {
            WpfColor blue   = (TryFindResource("ChartBlueColor")   as WpfColor?) ?? WpfColor.FromRgb(59,130,246);
            WpfColor orange = (TryFindResource("ChartOrangeColor") as WpfColor?) ?? WpfColor.FromRgb(249,115,22);
            WpfColor green  = (TryFindResource("ChartGreenColor")  as WpfColor?) ?? WpfColor.FromRgb(34,197,94);
            WpfColor purple = (TryFindResource("PurpleAccentColor") as WpfColor?) ?? WpfColor.FromRgb(139,92,246);
            WpfColor amber  = (TryFindResource("WarnAmberColor")   as WpfColor?) ?? WpfColor.FromRgb(245,158,11);

            // The last valid value from a circular buffer — the value gradient (Temp/Percent) needs "what it is now", not only the
            // metric's identity colour.
            float LastVal(float[] arr)
            {
                int i = (_chartIdx - 1 + ChartMaxPoints) % ChartMaxPoints;
                float v = arr[i];
                return float.IsNaN(v) ? 0f : v;
            }

            // YMax = 0 → dynamic auto-scale from the data
            _chartDefs["CpuTemp"]    = new("CPU Temperature",  blue,   c => DrawSingleTempChart(c, _chartCpu,      ResolveChartColor(blue,   LastVal(_chartCpu),      ChartValKind.Temp),    20f,  100f, "°",   "F0"), 20f,  100f, "°",   "F0");
            _chartDefs["CpuFreq"]    = new("CPU Frequency",    blue,   c => DrawSingleTempChart(c, _chartCpuFreq, ResolveChartColor(blue),                                                  0f,    0f, "MHz", "F0"),  0f,    0f, "MHz", "F0");
            _chartDefs["CpuLoad"]    = new("CPU Load",         green,  c => DrawSingleTempChart(c, _chartCpuUsage, ResolveChartColor(green,  LastVal(_chartCpuUsage), ChartValKind.Percent),  0f,  100f, "%",   "F0"),  0f,  100f, "%",   "F0");
            _chartDefs["CpuPower"]   = new("CPU Power (W)",    amber,  c => DrawSingleTempChart(c, _chartCpuPower, ResolveChartColor(amber),                                                 0f,    0f, "W",   "F1"),  0f,    0f, "W",   "F1");
            _chartDefs["GpuTemp"]    = new("GPU Temperature",  orange, c => DrawSingleTempChart(c, _chartGpu,      ResolveChartColor(orange, LastVal(_chartGpu),      ChartValKind.Temp),    20f,  100f, "°",   "F0"), 20f,  100f, "°",   "F0");
            _chartDefs["GpuLoad"]    = new("GPU Load",         orange, c => DrawSingleTempChart(c, _chartGpuLoad,  ResolveChartColor(orange, LastVal(_chartGpuLoad),  ChartValKind.Percent),  0f,  100f, "%",   "F0"),  0f,  100f, "%",   "F0");
            _chartDefs["GpuClock"]   = new("GPU Clock",        purple, c => DrawSingleTempChart(c, _chartGpuFreq,  ResolveChartColor(purple),                                                0f,    0f, "MHz", "F0"),  0f,    0f, "MHz", "F0");
            _chartDefs["GpuVram"]    = new("VRAM Used",        orange, c => DrawSingleTempChart(c, _chartGpuVram,  ResolveChartColor(orange),                                                0f,    0f, "MB",  "F0"),  0f,    0f, "MB",  "F0");
            _chartDefs["RamLoad"]    = new("RAM Used",         purple, c => DrawSingleTempChart(c, _chartRamUsage, ResolveChartColor(purple, LastVal(_chartRamUsage), ChartValKind.Percent),  0f,  100f, "%",   "F0"),  0f,  100f, "%",   "F0");
            _chartDefs["CpuVCore"]   = new("CPU VCore (V)",    purple, c => DrawSingleTempChart(c, _chartCpuVCore, ResolveChartColor(purple),                                                0.8f, 1.55f,"V",  "F3"), 0.8f, 1.55f, "V",  "F3");
            _chartDefs["GpuMemClock"]= new("GPU Mem Clock",    purple, c => DrawSingleTempChart(c, _chartGpuMemFreq,ResolveChartColor(purple),                                                0f,   0f, "MHz", "F0"),  0f,    0f, "MHz", "F0");
            _chartDefs["DiskTemp"]   = new("Disk Temperature", blue,   c => DrawSingleTempChart(c, _chartDiskTemp, ResolveChartColor(blue, LastVal(_chartDiskTemp), ChartValKind.Temp),     20f,   80f, "°",   "F0"), 20f,   80f, "°",   "F0");
            _chartDefs["SysPower"]   = new("System Power (W)", amber,  c => DrawSingleTempChart(c, _chartSysPower, ResolveChartColor(amber),                                                 0f,   0f, "W",   "F0"),  0f,    0f, "W",   "F0");
        }

