        internal void RowCpuCoreTemps_Click(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (FindName("CoreTempsExpandPanel") is not System.Windows.Controls.StackPanel panel) return;
            bool expanding = panel.Visibility != Visibility.Visible;
            panel.Visibility = expanding ? Visibility.Visible : Visibility.Collapsed;
            if (FindName("TxtCoreTempsChevron") is TextBlock chev) chev.Text = expanding ? "▾" : "›";
            if (expanding && _lastTempSnap?.CoreTemps.Count > 0)
                UpdateCoreTempsPanel(panel, _lastTempSnap);
        }

        private void UpdateCoreTempsPanel(System.Windows.Controls.StackPanel panel, SMDWin.Services.TempSnapshot? snap)
        {
            if (snap == null) return;
            panel.Children.Clear();
            var accent = TryFindResource("ChartGreenBrush") as System.Windows.Media.Brush ?? _brGreen;
            var secBrush = TryFindResource("TextSecondaryBrush") as System.Windows.Media.Brush ?? _brGray;

            // Safety fallback: if CoreTempsDetailed was not populated (it should be, but better not to lose the row from the UI),
            // build a minimal version from CoreTemps, without P/E labels.
            var entries = snap.CoreTempsDetailed.Count == snap.CoreTemps.Count && snap.CoreTempsDetailed.Count > 0
                ? snap.CoreTempsDetailed
                : snap.CoreTemps.Select((t, i) => new SMDWin.Services.CoreTempEntry { Index = i, Temp = t }).ToList();

            foreach (var entry in entries)
            {
                float t = entry.Temp;
                var row = new System.Windows.Controls.Grid { Margin = new Thickness(32, 0, 8, 0), MinHeight = 22 };
                row.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition());
                row.ColumnDefinitions.Add(new System.Windows.Controls.ColumnDefinition { Width = System.Windows.GridLength.Auto });

                string suffix = entry.Kind switch
                {
                    SMDWin.Services.CpuTopologyService.CoreKind.Performance => "  P",
                    SMDWin.Services.CpuTopologyService.CoreKind.Efficiency  => "  E",
                    _ => ""
                };
                var lbl = new TextBlock
                {
                    Text = $"Core #{entry.Index}{suffix}",
                    FontSize = Ui.FontS,
                    Foreground = secBrush,
                    VerticalAlignment = VerticalAlignment.Center
                };
                var val = new TextBlock
                {
                    Text = $"{TempUnit.Fmt(t)}",
                    FontSize = Ui.FontS,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = t > 85 ? _brRed : t > 70 ? _brOrange : accent,
                    TextAlignment = TextAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 4, 0)
                };
                System.Windows.Controls.Grid.SetColumn(val, 1);
                row.Children.Add(lbl);
                row.Children.Add(val);
                panel.Children.Add(row);
            }
        }

        // Temp & Stress: on the left either the CPU / GPU cards, or the 4 charts chosen from the sensor table ("My charts").
        private bool _stressChartsMode;
        private string _lastSensorClickTag = "";
        private DateTime _lastSensorClickUtc = DateTime.MinValue;

        internal void SensorRow_Click(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (sender is not FrameworkElement el || el.Tag is not string tag) return;
            if (_chartDefs.Count == 0) InitChartDefs();
            if (!_chartDefs.ContainsKey(tag)) return;

            // a double click must not add and then remove the same sensor
            var now = DateTime.UtcNow;
            if (tag == _lastSensorClickTag && (now - _lastSensorClickUtc).TotalMilliseconds < 450) return;
            _lastSensorClickTag = tag; _lastSensorClickUtc = now;

            // from the cards view: the first click only shows the charts (and adds the sensor if missing)
            if (!_stressChartsMode)
            {
                if (Array.IndexOf(_slotTags, tag) < 0) AddSensorToSlots(tag);
                SetStressChartsMode(true);
                return;
            }

            int existingSlot = Array.IndexOf(_slotTags, tag);
            if (existingSlot >= 0)
            {
                // removal: the charts below move up, the last slot stays empty
                for (int i = existingSlot; i < 3; i++) _slotTags[i] = _slotTags[i + 1];
                _slotTags[3] = "";
                if (_slotTags.All(string.IsNullOrEmpty)) { _slotTags[0] = tag; SetStressChartsMode(false); }
            }
            else AddSensorToSlots(tag);
            RefreshAllSlots();
        }

        /// <summary>Puts the sensor in the first free slot; with all 4 occupied, the oldest leaves and the rest move up.</summary>
        private void AddSensorToSlots(string tag)
        {
            int empty = Array.FindIndex(_slotTags, t => string.IsNullOrEmpty(t) || !_chartDefs.ContainsKey(t));
            if (empty < 0)
            {
                for (int i = 0; i < 3; i++) _slotTags[i] = _slotTags[i + 1];
                empty = 3;
            }
            _slotTags[empty] = tag;
            RefreshAllSlots();
        }

        private void RefreshAllSlots()
        {
            for (int i = 0; i < 4; i++)
            {
                UpdateSlotUI(i, _slotTags[i]);
                if (FindName("ChartSlot" + (i + 1)) is FrameworkElement slot)
                    slot.Visibility = string.IsNullOrEmpty(_slotTags[i]) ? Visibility.Collapsed : Visibility.Visible;
                if (_stressChartsMode && !string.IsNullOrEmpty(_slotTags[i])) ShowSlotChart(i, _slotTags[i]);
            }
            RefreshSlotCheckboxes();
        }

        /// <summary>The checkboxes in the table show what is on the charts — only while the charts are visible.</summary>
        private void RefreshSlotCheckboxes()
        {
            var accent = TryFindResource("AccentBrush") as System.Windows.Media.Brush ?? System.Windows.Media.Brushes.CornflowerBlue;
            foreach (var tag in _tagToChk.Keys)
                UpdateCheckbox(tag, _stressChartsMode && Array.IndexOf(_slotTags, tag) >= 0, accent);
        }

        private void SetStressChartsMode(bool on)
        {
            _stressChartsMode = on;
            if (FindName("StressLegacyCharts") is FrameworkElement charts) charts.Visibility = on ? Visibility.Visible : Visibility.Collapsed;
            if (StCpuCard != null) StCpuCard.Visibility = on ? Visibility.Collapsed : Visibility.Visible;
            if (StGpuCard != null) StGpuCard.Visibility = on ? Visibility.Collapsed : Visibility.Visible;
            RefreshAllSlots();
        }

        internal void StressChartsBack_Click(object sender, RoutedEventArgs e) => SetStressChartsMode(false);

        // "My charts": a history with one point per second for each sensor that can be charted, drawn with MiniLineChart
        // (flows smoothly, like the charts in the CPU / GPU cards). The last two series: the running CPU / GPU test.
        private static readonly string[] SlotSeriesTags =
            { "CpuTemp", "GpuTemp", "CpuFreq", "CpuLoad", "RamLoad", "CpuPower", "GpuLoad", "GpuClock", "GpuVram", "CpuVCore", "GpuMemClock", "SysPower", "DiskTemp" };
        private readonly SMDWin.Services.SecondHistory _slotHist = new(SlotSeriesTags.Length + 2);
        private static readonly string[] SlotCanvasNames = { "CpuTempCanvas", "CpuFreqCanvas", "CpuUsageCanvas", "GpuTempCanvas" };

        /// <summary>The values in the order of <see cref="SlotSeriesTags"/>; called on every read, whatever page is shown.</summary>
        private void PushSlotHistory(float[] values, bool gap)
        {
            try
            {
                var v = new float[SlotSeriesTags.Length + 2];
                for (int i = 0; i < SlotSeriesTags.Length; i++) v[i] = i < values.Length ? values[i] : float.NaN;
                v[^2] = _cpuStress.Running ? 1f : 0f;
                v[^1] = _gpuStress.IsRunning ? 1f : 0f;
                _slotHist.Push(DateTime.UtcNow, v, gap: gap, maxInterpolated: ChartInterpolateMaxSlots);
            }
            catch (Exception ex) { AppLogger.Swallowed(ex); }
        }

        /// <summary>The chart of a slot: MiniLineChart for sensors with history, the older canvas for the rest (fans).</summary>
        private void ShowSlotChart(int slot, string tag)
        {
            if (FindName("SlotChart" + (slot + 1)) is not MiniLineChart chart) return;
            int si = Array.IndexOf(SlotSeriesTags, tag);
            bool live = si >= 0;
            chart.Visibility = live ? Visibility.Visible : Visibility.Collapsed;
            if (FindName(SlotCanvasNames[slot]) is FrameworkElement cv) cv.Visibility = live ? Visibility.Collapsed : Visibility.Visible;
            if (!live) return;

            var s = SettingsService.Current;
            chart.Min = 0; chart.Max = double.NaN; chart.WarnLine = double.NaN; chart.WarnText = null; chart.ScaleText = null; chart.NiceMax = null;
            switch (tag)
            {
                case "CpuTemp": case "GpuTemp": case "DiskTemp":
                    double warn = tag == "CpuTemp" ? s.TempWarnCpu : tag == "GpuTemp" ? s.TempWarnGpu : double.NaN;
                    chart.Min = 20; chart.Max = tag == "DiskTemp" ? 80 : 105; chart.WarnLine = warn;
                    chart.WarnText = double.IsFinite(warn) && warn > 0 ? $"{TempUnit.Fmt(warn, 0, true)} limit" : null;
                    break;
                case "CpuLoad": case "GpuLoad": case "RamLoad":
                    chart.Max = 100; break;
                case "CpuFreq": case "GpuClock": case "GpuMemClock":
                    chart.ScaleText = v => v >= 1000 ? $"{v / 1000:0.#} GHz" : $"{v:0} MHz"; break;
                case "CpuPower": case "SysPower":
                    chart.ScaleText = v => $"{v:0} W"; break;
                case "GpuVram":
                    chart.ScaleText = v => v >= 1024 ? $"{v / 1024:0.#} GB" : $"{v:0} MB"; break;
                case "CpuVCore":
                    chart.Min = 0.6; chart.ScaleText = v => $"{v:0.00} V"; break;
            }
            bool gpu = tag.StartsWith("Gpu", StringComparison.Ordinal);
            chart.ShowMarksA = s.StressChartShowTests;
            chart.TintMarksA = s.StressChartMarkStyle != "Line";
            chart.ShowHistory(_slotHist, Math.Clamp(StressChartPoints, 30, 3600), si, -1,
                              SlotSeriesTags.Length + (gpu ? 1 : 0), -1);
        }

        private void UpdateSlotUI(int slot, string tag)
        {
            string[] labels = { "TxtChartLabel1", "TxtChartLabel2", "TxtChartLabel3", "TxtChartLabel4" };
            string[] vals   = { "TxtChartVal1",   "TxtChartVal2",   "TxtChartVal3",   "TxtChartVal4"   };
            if (slot < 0 || slot > 3) return;

            string labelName = labels[slot];
            string valName   = vals[slot];

            if (FindName(labelName) is TextBlock lbl)
                lbl.Text = string.IsNullOrEmpty(tag) || !_chartDefs.TryGetValue(tag, out var def)
                    ? ""
                    : def.Label;

            if (FindName(valName) is TextBlock val)
            {
                val.Text = "—";
                if (!string.IsNullOrEmpty(tag) && _chartDefs.TryGetValue(tag, out var d2))
                    val.Foreground = new SolidColorBrush(d2.Color);
            }
        }

        private static readonly Dictionary<string, string> _tagToRow = new()
        {
            ["CpuTemp"]    = "RowCpuTemp",    ["CpuFreq"]    = "RowCpuFreq",
            ["CpuLoad"]    = "RowCpuLoad",    ["CpuPower"]   = "RowCpuPower",
            ["GpuTemp"]    = "RowGpuTemp",    ["GpuLoad"]    = "RowGpuLoad",
            ["GpuClock"]   = "RowGpuClock",   ["GpuVram"]    = "RowGpuVram",   // original
            ["RamLoad"]    = "RowRamLoad",
            ["CpuVCore"]   = "RowCpuVCore",   ["GpuMemClock"]= "RowGpuMemClock",
            ["SysPower"]   = "RowGpuPower",
        };

        private void UpdateCheckbox(string tag, bool active, System.Windows.Media.Brush accent)
        {
            // Small checkbox — solid background when active
            if (_tagToChk.TryGetValue(tag, out var chkName) &&
                FindName(chkName) is Border chk)
            {
                if (active)
                {
                    chk.SetResourceReference(Border.BackgroundProperty, "AccentBrush");
                    chk.SetResourceReference(Border.BorderBrushProperty, "AccentBrush");
                    // Bifare vizuala: litera ✓ in checkbox
                    if (chk.Child is System.Windows.Controls.TextBlock existTb)
                        existTb.Text = "✓";
                    else
                    {
                        var tb = new System.Windows.Controls.TextBlock
                        {
                            Text = "✓", FontSize = 9, FontWeight = FontWeights.Bold,
                            Foreground = System.Windows.Media.Brushes.White,
                            HorizontalAlignment = System.Windows.HorizontalAlignment.Center,
                            VerticalAlignment = System.Windows.VerticalAlignment.Center,
                        };
                        chk.Child = tb;
                    }
                }
                else
                {
                    chk.Background  = System.Windows.Media.Brushes.Transparent;
                    chk.SetResourceReference(Border.BorderBrushProperty, "CardBorderBrush");
                    chk.Child = null;
                }
            }

            if (_tagToRow.TryGetValue(tag, out var tRowName) && FindName(tRowName) is FrameworkElement tRow)
            {
                if (active)
                {
                    int activeSlot = Array.IndexOf(_slotTags, tag);
                    tRow.ToolTip = activeSlot >= 0
                        ? $"Active in slot {activeSlot + 1} — click to remove"
                        : "Active — click to remove";
                }
                else
                {
                    tRow.ToolTip = null;
                }
            }
        }

        private static readonly WpfColor _chartLightBlue = WpfColor.FromRgb(0x62, 0xA0, 0xEA); // GNOME Adwaita light blue
        private enum ChartValKind { None, Temp, Percent }
        private WpfColor ResolveChartColor(WpfColor identityColor, float? value = null, ChartValKind kind = ChartValKind.None)
        {
            switch (SettingsService.Current.ChartColorMode)
            {
                case "Accent":
                    try
                    {
                        if (TryFindResource("DataBrush") is SolidColorBrush accentB) return accentB.Color;
                    }
                    catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    return identityColor;
                case "LightBlue": return _chartLightBlue;
                case "Gray":      return WpfColor.FromRgb(0x9C, 0xA3, 0xAF);
                case "Gradient":
                    if (value.HasValue && kind == ChartValKind.Temp)    return GradientTempColor(value.Value);
                    if (value.HasValue && kind == ChartValKind.Percent) return GradientPercentColor(value.Value);
                    return _chartLightBlue; // metrics without a natural gradient (Freq/Power/VCore) — fall back to light blue
                default:          return identityColor; // "Colored"
            }
        }

        private bool IsMonoChartMode => SettingsService.Current.ChartColorMode != "Colored";

        private void DrawSlotChart(System.Windows.Controls.Canvas canvas, string tag,
            SMDWin.Services.TempSnapshot? snap, int idx, string valTbName)
        {
            if (canvas == null) return;
            var blue   = ResolveChartColor((TryFindResource("ChartBlueColor")   as WpfColor?) ?? WpfColor.FromRgb(59,130,246));
            var orange = ResolveChartColor((TryFindResource("ChartOrangeColor") as WpfColor?) ?? WpfColor.FromRgb(249,115,22));
            var green  = ResolveChartColor((TryFindResource("ChartGreenColor")  as WpfColor?) ?? WpfColor.FromRgb(34,197,94));
            var purple = ResolveChartColor((TryFindResource("PurpleAccentColor") as WpfColor?) ?? WpfColor.FromRgb(139,92,246));
            var amber  = ResolveChartColor((TryFindResource("WarnAmberColor")   as WpfColor?) ?? WpfColor.FromRgb(245,158,11));

            WpfColor? valueTextColor = tag switch
            {
                "CpuFreq" or "CpuLoad" or "CpuTemp"                  => blue,
                "GpuTemp" or "GpuLoad" or "GpuClock" or "GpuVram" or "GpuMemClock" => orange,
                "RamLoad"                                            => green,
                "CpuVCore"                                           => purple,
                "CpuPower" or "SysPower"                             => amber,
                _                                                    => (WpfColor?)null,
            };

            string dispVal = "—";
            try
            {
                switch (tag)
                {
                    case "CpuTemp":
                        DrawSingleTempChart(canvas, _chartCpu, ResolveChartColor(blue, snap?.CpuTemp, ChartValKind.Temp), 20f, 100f, "°", "F0",
                            SettingsService.Current.TempWarnCpu);
                        dispVal = snap?.CpuTemp.HasValue == true ? $"{TempUnit.Fmt(snap.CpuTemp.Value)}" : "—";
                        if (snap?.CpuTemp.HasValue == true) valueTextColor = TempColorGradient(snap.CpuTemp.Value);
                        break;
                    case "CpuFreq":
                        DrawSingleTempChart(canvas, _chartCpuFreq, blue, 0f, 0f, "MHz", "F0");
                        dispVal = snap?.CpuFreqMHz.HasValue == true
                            ? (snap.CpuFreqMHz.Value >= 1000 ? $"{snap.CpuFreqMHz.Value/1000f:F2} GHz" : $"{snap.CpuFreqMHz.Value:F0} MHz")
                            : "—";
                        break;
                    case "CpuLoad":
                        DrawSingleTempChart(canvas, _chartCpuUsage, ResolveChartColor(blue, _cachedCpuPct >= 0 ? _cachedCpuPct : null, ChartValKind.Percent), 0f, 100f, "%", "F0");
                        dispVal = _cachedCpuPct >= 0 ? $"{_cachedCpuPct:F0}%" : "—";
                        if (_cachedCpuPct >= 0) valueTextColor = GetPercentColor(_cachedCpuPct);
                        break;
                    case "CpuPower":
                        DrawSingleTempChart(canvas, _chartCpuPower, amber, 0f, 0f, "W", "F1");
                        dispVal = snap?.CpuPowerW.HasValue == true ? $"{snap.CpuPowerW.Value:F1} W" : "—";
                        break;
                    case "GpuTemp":
                        DrawSingleTempChart(canvas, _chartGpu, ResolveChartColor(orange, snap?.GpuTemp, ChartValKind.Temp), 20f, 100f, "°", "F0",
                            SettingsService.Current.TempWarnGpu);
                        dispVal = snap?.GpuTemp.HasValue == true ? $"{TempUnit.Fmt(snap.GpuTemp.Value)}" : "—";
                        if (snap?.GpuTemp.HasValue == true) valueTextColor = TempColorGradient(snap.GpuTemp.Value, isGpu: true);
                        break;
                    case "GpuLoad":
                        DrawSingleTempChart(canvas, _chartGpuLoad, ResolveChartColor(orange, snap?.GpuLoadPct, ChartValKind.Percent), 0f, 100f, "%", "F0");
                        dispVal = snap?.GpuLoadPct.HasValue == true ? $"{snap.GpuLoadPct.Value:F0}%" : "—";
                        if (snap?.GpuLoadPct.HasValue == true) valueTextColor = GetPercentColor(snap.GpuLoadPct.Value);
                        break;
                    case "GpuClock":
                        DrawSingleTempChart(canvas, _chartGpuFreq, purple, 0f, 0f, "MHz", "F0");
                        dispVal = snap?.GpuFreqMHz.HasValue == true
                            ? (snap.GpuFreqMHz.Value >= 1000 ? $"{snap.GpuFreqMHz.Value/1000f:F2} GHz" : $"{snap.GpuFreqMHz.Value:F0} MHz")
                            : "—";
                        break;
                    case "GpuVram":
                        DrawSingleTempChart(canvas, _chartGpuVram, orange, 0f, 0f, "MB", "F0");
                        dispVal = snap?.GpuMemUsedMB.HasValue == true ? $"{snap.GpuMemUsedMB.Value:F0} MB" : "—";
                        break;
                    case "RamLoad":
                        float ramPct2 = _cachedTotalRamMB > 0 && _cachedAvailRamMB >= 0
                            ? Math.Clamp(100f * (1f - _cachedAvailRamMB / _cachedTotalRamMB), 0f, 100f) : -1f;
                        DrawSingleTempChart(canvas, _chartRamUsage, ResolveChartColor(green, ramPct2 >= 0 ? ramPct2 : null, ChartValKind.Percent), 0f, 100f, "%", "F0");
                        dispVal = ramPct2 >= 0 ? $"{ramPct2:F0}%" : "—";
                        if (ramPct2 >= 0) valueTextColor = GetPercentColor(ramPct2);
                        break;
                    case "CpuVCore":
                        DrawSingleTempChart(canvas, _chartCpuVCore, purple, 0.8f, 1.55f, "V", "F3");
                        dispVal = snap?.CpuVCoreV.HasValue == true ? $"{snap.CpuVCoreV.Value:F3} V" : "—";
                        break;
                    case "GpuMemClock":
                        DrawSingleTempChart(canvas, _chartGpuMemFreq, purple, 0f, 0f, "MHz", "F0");
                        dispVal = snap?.GpuMemFreqMHz.HasValue == true
                            ? (snap.GpuMemFreqMHz.Value >= 1000 ? $"{snap.GpuMemFreqMHz.Value/1000f:F2} GHz" : $"{snap.GpuMemFreqMHz.Value:F0} MHz")
                            : "—";
                        break;
                    case "DiskTemp":
                        {
                            float dt = CurrentDiskTempForChart();
                            DrawSingleTempChart(canvas, _chartDiskTemp, ResolveChartColor(blue, float.IsNaN(dt) ? null : dt, ChartValKind.Temp), 20f, 80f, "°", "F0");
                            dispVal = float.IsNaN(dt) ? "—" : $"{TempUnit.Fmt(dt)}";
                        }
                        break;
                    case "SysPower":
                        DrawSingleTempChart(canvas, _chartSysPower, amber, 0f, 0f, "W", "F0");
                        {
                            float cpuW2 = snap?.CpuPowerW ?? 0f;
                            float gpuW2 = snap?.GpuPowerW ?? 0f;
                            dispVal = (cpuW2 > 0 || gpuW2 > 0) ? $"{cpuW2 + gpuW2 + 45f:F0} W" : "—";
                        }
                        break;
                    default:
                        // Empty slot — clear the canvas and show text
                        {
                            var dvEmpty2 = new DrawingVisual();
                            using (var dc2 = dvEmpty2.RenderOpen())
                            {
                                dc2.DrawRectangle(_brBgRect, null, new Rect(0,0,canvas.ActualWidth,canvas.ActualHeight));
                                var ft2 = _chartTypeface;
                                var dpiInfo2 = VisualTreeHelper.GetDpi(canvas);
                                var emptyLbl = new FormattedText("— empty slot —",
                                    System.Globalization.CultureInfo.InvariantCulture,
                                    System.Windows.FlowDirection.LeftToRight, ft2, 11,
                                    new SolidColorBrush(WpfColor.FromArgb(80,180,180,180)), dpiInfo2.PixelsPerDip);
                                dc2.DrawText(emptyLbl, new System.Windows.Point(
                                    canvas.ActualWidth / 2 - emptyLbl.Width / 2,
                                    canvas.ActualHeight / 2 - emptyLbl.Height / 2));
                            }
                            RenderToCanvas(canvas, dvEmpty2, canvas.ActualWidth, canvas.ActualHeight);
                            // Remove the slot from the dirty flag to force a redraw on the next activation
                            _slotDrawn.Remove(canvas);
                        }
                        break;
                }
            }
            catch (Exception ex) { AppLogger.Debug($"DrawSlotChart({tag}): {ex.Message}"); }

            // Update the current value in the chart header
            if (tag != "")
            {
                if (FindName(valTbName) is TextBlock vt)
                {
                    vt.Text = dispVal;
                    vt.Foreground = valueTextColor.HasValue
                        ? new SolidColorBrush(valueTextColor.Value)
                        : (TryFindResource("TextPrimaryBrush") as System.Windows.Media.Brush) ?? System.Windows.Media.Brushes.Gray;
                }
            }
            else
            {
                // Empty slot: clear the value and the label
                if (FindName(valTbName) is TextBlock vtEmpty) vtEmpty.Text = "";
                // Find the matching label too (TxtChartVal1→TxtChartLabel1 etc.)
                string lblName = valTbName.Replace("TxtChartVal", "TxtChartLabel");
                if (FindName(lblName) is TextBlock lblEmpty) lblEmpty.Text = "—";
            }
        }
    }
}
